package com.fitnutri.backend.records.food;
import com.fitnutri.backend.support.*;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.records.*;
import java.math.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("integration-test")
class FoodEntryPreviewIT {
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @Autowired FoodEntryPreviewService previews;@Autowired JdbcTemplate jdbc;
 long owner,other,ref;UUID singleId,dishId,ingredientId;
 @BeforeEach void setup()throws Exception{try(var c=DB.connect()){var users=UxV3Fixtures.usersAndDatedWeights(c);owner=users.ownerId();other=users.otherOwnerId();}long dataset=jdbc.queryForObject("INSERT INTO food_dataset(name,release_name,revision,nutrient_policy,source_note,source_url,content_sha256,verified) VALUES(?,'synthetic','test','SYNTHETIC','Synthetic test only','https://example.test/synthetic',?,true) RETURNING id",Long.class,"SYNTHETIC-"+UUID.randomUUID(),"a".repeat(64));ref=jdbc.queryForObject("INSERT INTO food_reference(public_food_key,dataset_id,display_name,is_active,energy_kj_100g,protein_g_100g,fat_g_100g,carbs_g_100g) VALUES(?,?,'Synthetic food',true,1000,1,2,3) RETURNING id",Long.class,"SYNTHETIC-"+UUID.randomUUID(),dataset);singleId=UUID.randomUUID();dishId=UUID.randomUUID();ingredientId=UUID.randomUUID();}
 FoodEntryInputs.Single single(){return new FoodEntryInputs.Single(singleId,Long.toString(ref),new BigDecimal("100"),MealType.LUNCH,null,null);}
 FoodEntryInputs.Dish dish(String name,int denominator){return new FoodEntryInputs.Dish(dishId,name,MealType.LUNCH,"FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",denominator),List.of(new FoodEntryInputs.Ingredient(ingredientId,Long.toString(ref),new BigDecimal("300"),null,null)),null);}
 FoodEntryInputs.PreviewRequest request(List<FoodEntryInputs.Entry> entries){return new FoodEntryInputs.PreviewRequest(LocalDate.of(2026,10,17),"Australia/Sydney",RecordSource.MANUAL,entries);}
 @Test void mixedPreviewIsAuthorityWithoutAnyPersistenceAndOnlyCalculationChangesInvalidateFingerprint(){long before=jdbc.queryForObject("SELECT count(*) FROM food_record",Long.class);var result=previews.previewNewBatch(owner,request(List.of(single(),dish("First label",3))));assertEquals(new BigDecimal("2000.000"),result.totals().energyKj());assertEquals(2,result.entries().size());assertEquals(before,jdbc.queryForObject("SELECT count(*) FROM food_record",Long.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM food_dish_record",Long.class));assertEquals(result.fingerprint(),previews.previewNewBatch(owner,request(List.of(single(),dish("Changed label",3)))).fingerprint());assertNotEquals(result.inputSignature(),previews.previewNewBatch(owner,request(List.of(single(),dish("Changed label",3)))).inputSignature());assertNotEquals(result.fingerprint(),previews.previewNewBatch(owner,request(List.of(single(),dish("First label",2)))).fingerprint());}
 @Test void inactiveReferenceExceptionRequiresExactOwnedLeafAndVersion(){long id=jdbc.queryForObject("INSERT INTO food_record(user_id,created_at,recorded_at,recorded_date,client_entry_id,source,food_name,quantity_grams,meal_type,food_reference_id,data_quality,energy_kj,protein_grams,fat_grams,carbs_grams) VALUES(?,now(),now(),DATE '2026-10-17',?,'MANUAL','Synthetic old food',100,'LUNCH',?,'CURRENT',123.456,1,2,3) RETURNING id",Long.class,owner,singleId,ref);jdbc.update("UPDATE food_reference SET is_active=false WHERE id=?",ref);assertThrows(BusinessException.class,()->previews.previewNewBatch(owner,request(List.of(single()))));var correction=new FoodEntryInputs.CorrectionRequest(0L,LocalDate.of(2026,10,17),"Australia/Sydney",single());assertEquals(new BigDecimal("123.456"),previews.previewOwnedRoot(owner,"single",id,correction).totals().energyKj());assertThrows(BusinessException.class,()->previews.previewOwnedRoot(other,"single",id,correction));assertThrows(BusinessException.class,()->previews.previewOwnedRoot(owner,"single",id,new FoodEntryInputs.CorrectionRequest(1L,correction.recordDate(),correction.zone(),single())));var changed=new FoodEntryInputs.Single(singleId,Long.toString(ref),new BigDecimal("200"),MealType.LUNCH,null,null);assertEquals(new BigDecimal("2000.000"),previews.previewOwnedRoot(owner,"single",id,new FoodEntryInputs.CorrectionRequest(0L,correction.recordDate(),correction.zone(),changed)).totals().energyKj());jdbc.update("UPDATE food_record SET energy_kj=NULL WHERE id=?",id);assertNull(previews.previewOwnedRoot(owner,"single",id,correction).totals().energyKj());}
 @Test void identityCardinalityOriginAndDateErrorsAreRealRejections(){assertThrows(BusinessException.class,()->previews.previewNewBatch(owner,request(List.of(single(),single()))));assertThrows(BusinessException.class,()->previews.previewNewBatch(owner,request(List.of())));assertThrows(BusinessException.class,()->previews.previewNewBatch(owner,new FoodEntryInputs.PreviewRequest(LocalDate.of(2999,1,1),"Australia/Sydney",RecordSource.MANUAL,List.of(single()))));var illegal=new FoodEntryInputs.Dish(dishId,"Other origin",MealType.LUNCH,"PERSONAL",Map.of("kind","PERSONAL"),List.of(new FoodEntryInputs.Ingredient(ingredientId,Long.toString(ref),BigDecimal.ONE,null,null)),"999999");assertThrows(BusinessException.class,()->previews.previewNewBatch(owner,request(List.of(illegal))));}
}
